function positionRenewalModalConnector(){const layout=document.querySelector('.renewal-requirements-layout'),anchor=layout?.querySelector('.renewal-modal-anchor'),prototype=layout?.querySelector('.renewal-modal-prototype'),svg=layout?.querySelector('.renewal-modal-connector-svg'),line=layout?.querySelector('[data-renewal-modal-connector]');if(!layout||!anchor||!prototype||!svg||!line)return;const base=layout.getBoundingClientRect(),a=anchor.getBoundingClientRect(),p=prototype.getBoundingClientRect(),x1=a.right-base.left+4,y1=a.top-base.top+a.height/2,x2=p.left-base.left+15,y2=p.bottom-base.top-20,width=Math.max(layout.clientWidth,x2+30),height=Math.max(layout.clientHeight,y2+20);svg.style.width=`${width}px`;svg.style.height=`${height}px`;line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2)}

function bindRenewalModalRequirement(){document.querySelectorAll('[data-renewal-modal-state]').forEach(button=>button.onclick=()=>{state.stateId=button.dataset.renewalModalState;state.noteMode='change';renderAll()});document.querySelectorAll('[data-renewal-modal-product]').forEach(button=>button.onclick=()=>{state.renewalProduct=button.dataset.renewalModalProduct;renderNotes()});document.querySelectorAll('[data-renewal-modal-tier]').forEach(button=>button.onclick=()=>{state.renewalTier=button.dataset.renewalModalTier;renderNotes()});document.querySelectorAll('[data-renewal-modal-buy]').forEach(button=>button.onclick=()=>goToRepurchasePayment());requestAnimationFrame(positionRenewalModalConnector)}

function syncRenewalPreview(){if(state.pageId!=='renewal')return;const profile=$('.renewal-profile');const summary=$('.renewal-summary');if(!profile||!summary)return;const name=profile.querySelector('strong');const type=profile.querySelector('span');const id=profile.querySelector('small');const tier=state.renewalTier==='svip'?'SVIP':'VIP';if(state.stateId==='canceled'){name.textContent='书房听雨';type.textContent=`${tier}会员 · 已取消自动续费`;id.textContent='ID：10082361';summary.innerHTML='<p><span>会员状态：</span><strong>已取消续费</strong></p><p><span>权益到期：</span><strong>2026年10月21日</strong></p>'}else if(state.stateId==='expired'){name.textContent='书房听雨';type.textContent=`${tier}会员 · 已到期`;id.textContent='ID：10082361';summary.innerHTML='<p><span>会员状态：</span><strong>已到期</strong></p>'}}

function openRepurchaseModal(){document.querySelector('[data-repurchase-layer]')?.classList.add('show')}

function closeRepurchaseModal(){document.querySelector('[data-repurchase-layer]')?.classList.remove('show')}

function goToRepurchasePayment(){const layer=document.querySelector('[data-repurchase-layer]'),isUpgrade=layer?.dataset.modalKind==='upgrade',fromMine=state.pageId==='mine',info=fromMine?mineStateInfo():null;const tier=fromMine?(isUpgrade?'svip':info.type.toLowerCase()):(state.renewalTier==='svip'?'svip':'vip');const plan=fromMine?(isUpgrade?(info.type==='VIP'?(info.product==='连续包年'?'annual':'monthly'):'life'):(info.card==='单次卡'?'month1':info.product==='连续包年'?'annual':'monthly')):(state.renewalProduct==='annual'?'annual':'monthly');state.paymentRenewalDate=null;state.pageId='payment';state.stateId='default';state.paymentTab=tier;state.paymentPlan=plan;state.paymentPlanScrollLeft=0;state.noteMode='page';state.pageNoteRequested=true;state.activeAnnotation=null;renderAll()}

function bindRepurchaseModal(){if(state.pageId!=='renewal')return;const layer=document.querySelector('[data-repurchase-layer]'),buy=layer?.querySelector('[data-repurchase-buy]');document.querySelector('[data-repurchase-close]')?.addEventListener('click',closeRepurchaseModal);buy?.addEventListener('click',()=>{state.paymentAgreed=false;goToRepurchasePayment()});layer?.addEventListener('click',event=>{if(event.target===event.currentTarget)closeRepurchaseModal()})}

function bindRenewalToggle(){if(state.pageId!=='renewal')return;const summary=$('.renewal-summary');if(!summary)return;const label=state.stateId==='active'?'已开启自动续费':state.stateId==='canceled'?'自动续费':'再次续费';let row=summary.querySelector('.renewal-auto-row');if(!row){summary.insertAdjacentHTML('beforeend','<p class="renewal-auto-row"><span></span><label class="renewal-toggle"><input type="checkbox"><i></i></label></p>');row=summary.querySelector('.renewal-auto-row')}row.querySelector('span').textContent=label;const input=row.querySelector('input');input.checked=state.stateId==='active';input.disabled=false;input.onclick=event=>{if(state.stateId==='canceled'||state.stateId==='expired'){event.preventDefault();openRepurchaseModal()}};input.onchange=()=>{if(state.stateId==='active'&&!input.checked){input.checked=true;state.sheetAction='renewal-cancel';$('#sheetTitle').textContent='关闭自动续费';$('#sheetText').textContent='关闭后，当前 VIP 会员权益可继续使用到 2026 年 10 月 21 日，到期后自动转为普通用户，且后续将不再产生扣费。';$('#confirm').textContent='确认';$('#cancel').textContent='取消';$('#mask').classList.add('show');$('#sheet').classList.add('show')}}}

function renderRenewalToggle(){bindRenewalToggle()}

function showRenewalAction(action){const content={protocol:['自动续费协议','用户开通连续商品后，将按照页面展示的订阅周期和金额自动续费。用户可随时关闭自动续费；关闭后，当前会员权益继续有效至到期日，到期后不再产生后续扣费。']}[action];if(!content)return;clearTextSelection();state.sheetAction=`renewal-${action}`;$('#sheetTitle').textContent=content[0];$('#sheetText').textContent=content[1];$('#confirm').textContent='知道了';$('#cancel').textContent='关闭';$('#mask').classList.add('show');$('#sheet').classList.add('show')}

function bindRenewalFooter(){if(state.pageId!=='renewal')return;const renewal=$('.renewal');if(!renewal)return;let links=renewal.querySelector('.renewal-action-links');if(!links){renewal.insertAdjacentHTML('beforeend','<nav class="renewal-action-links" aria-label="续费服务操作"><button class="renewal-protocol-link" data-renewal-action="protocol">自动续费协议</button></nav>');links=renewal.querySelector('.renewal-action-links')}links.querySelectorAll('[data-renewal-action]').forEach(button=>button.onclick=()=>showRenewalAction(button.dataset.renewalAction))}
const showRenewalActionBase=showRenewalAction;
showRenewalAction=function(action){showRenewalActionBase(action);const actions=document.querySelector('.sheet-actions');const single=action==='protocol';actions?.classList.toggle('single',single);if(single)$('#cancel').textContent='知道了'}

window.workspacePageBindings.renewal=bindRepurchaseModal;
